    public function useWebserviceReplyQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinWebserviceReply($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'WebserviceReply', 'WebserviceReplyQuery');
    }

    /**
     * Filter the query by a related Forma object
     *
     * @param   Forma|PropelObjectCollection $forma  the related object to use as filter
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return                 ModuloQuery The current query, for fluid interface
     * @throws PropelException - if the provided filter is invalid.
     */
    public function filterByForma($forma, $comparison = null)
    {
        if ($forma instanceof Forma) {
            return $this
                ->addUsingAlias(ModuloPeer::MODULO_ID, $forma->getModuloId(), $comparison);
        } elseif ($forma instanceof PropelObjectCollection) {
            return $this
                ->useFormaQuery()
                ->filterByPrimaryKeys($forma->getPrimaryKeys())
                ->endUse();
        } else {
            throw new PropelException('filterByForma() only accepts arguments of type Forma or PropelCollection');
        }
    }

    /**
     * Adds a JOIN clause to the query using the Forma relation
     *
     * @param     string $relationAlias optional alias for the relation
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return ModuloQuery The current query, for fluid interface
     */
    public function joinForma($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        $tableMap = $this->getTableMap();
        $relationMap = $tableMap->getRelation('Forma');

        // create a ModelJoin object for this join
        $join = new ModelJoin();
        $join->setJoinType($joinType);
        $join->setRelationMap($relationMap, $this->useAliasInSQL ? $this->getModelAlias() : null, $relationAlias);
        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'Forma');
        }

        return $this;
    }

    /**
     * Use the Forma relation Forma object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   FormaQuery A secondary query class using the current class as primary query
     */
    public function useFormaQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinForma($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Forma', 'FormaQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   Modulo $modulo Object to remove from the list of results
     *
     * @return ModuloQuery The current query, for fluid interface
     */
    public function prune($modulo = null)
    {
        if ($modulo) {
            $this->addUsingAlias(ModuloPeer::MODULO_ID, $modulo->getModuloId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
